class Solution(object):
    def minDeletionSize(self, A):
        """
        :type A: List[str]
        :rtype: int
        """
        if not A:
            return 0

        n = len(A[0])
        m = len(A)
        dp = [1] * n  # dp[i] 表示以第 i 列為結尾的 LIS 長度

        for i in range(n):
            for j in range(i):
                try:
                    if all(A[k][j] <= A[k][i] for k in range(m)):
                        dp[i] = max(dp[i], dp[j] + 1)
                except IndexError:
                    pass

        return n - max(dp)
